export interface ConnectorConfig {
  /** Trello API key (from TRELLO_API_KEY environment variable) */
  trelloApiKey: string;
  /** Trello API token (from TRELLO_API_TOKEN environment variable) */
  trelloApiToken: string;
  /** The ID of the checklist on the Trello card where the item will be added */
  checklistId: string;
  /** Optional injected fetch for testing */
  fetch?: typeof fetch;
}

export interface GoogleCalendarWebhookPayload {
  event: string;
  event_id: string;
  account_id: string;
  meet_link: string;
  attendees: Array<{ email: string }>;
}

export interface TrelloChecklistItemResponse {
  id: string;
  idChecklist: string;
  idBoard: string;
  name: string;
  state: string;
}

export interface HandleResult {
  checklistItemId: string;
  checklistId: string;
  boardId: string;
  itemName: string;
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? globalThis.fetch;
}

function validatePayload(payload: unknown): asserts payload is GoogleCalendarWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object');
  }
  const p = payload as Record<string, unknown>;
  if (!Array.isArray(p.attendees) || p.attendees.length === 0) {
    throw new Error('Payload must contain a non-empty attendees array');
  }
  const firstAttendee = p.attendees[0] as Record<string, unknown> | undefined;
  if (!firstAttendee || typeof firstAttendee.email !== 'string' || !firstAttendee.email.trim()) {
    throw new Error('First attendee must have a non-empty email field');
  }
}

export async function handle(
  payload: GoogleCalendarWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload);

  const firstAttendeeEmail = payload.attendees[0].email.trim();
  const fetch = getFetch(config);

  const url = new URL(`https://api.trello.com/1/checklists/${encodeURIComponent(config.checklistId)}/checkItems`);
  url.searchParams.set('key', config.trelloApiKey);
  url.searchParams.set('token', config.trelloApiToken);
  url.searchParams.set('value', firstAttendeeEmail);
  url.searchParams.set('pos', 'bottom');

  const response = await fetch(url.toString(), {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
  });

  if (!response.ok) {
    throw new Error(`Trello API error: ${response.status} ${response.statusText} for POST ${url.pathname}`);
  }

  const data = (await response.json()) as TrelloChecklistItemResponse;

  return {
    checklistItemId: data.id,
    checklistId: data.idChecklist,
    boardId: data.idBoard,
    itemName: data.name,
  };
}

